<?php
require_once __DIR__.'/../../../config/config.php';
require_once __DIR__.'/../../../helpers/auth.php';
require_once __DIR__.'/../../../helpers/permissions_v2.php';
require_once __DIR__.'/../../../helpers/report_pagination.php';
require_once __DIR__.'/../../../services/HealthEncounterService.php';
require_login();
$actorUserId=(int)($_SESSION['user_id']??0);$actorChurchId=(int)($_SESSION['church_id']??0);$superAdmin=is_super_admin();if($actorChurchId<=0&&$actorUserId){$s=$conn->prepare('SELECT church_id FROM users WHERE id=?');$s->bind_param('i',$actorUserId);$s->execute();$actorChurchId=(int)($s->get_result()->fetch_assoc()['church_id']??0);$s->close();}
$service=new HealthEncounterService($conn,$actorUserId,$actorChurchId,$superAdmin);$churchId=$superAdmin?max(0,(int)($_GET['church_id']??$actorChurchId)):$actorChurchId;if($churchId<=0||!$service->authorize('view_individual_health_report',$churchId)){http_response_code(403);require __DIR__.'/../../errors/403.php';exit;}$canExport=$service->authorize('export_health_report',$churchId);$search=trim((string)($_GET['person']??''));$types='i';$params=[$churchId];$outerWhere=' WHERE ranked.row_number=1';if($search!==''){$outerWhere.=" AND (ranked.person_name LIKE CONCAT('%',?,'%') OR ranked.identifier LIKE CONCAT('%',?,'%'))";$types.='ss';array_push($params,$search,$search);}
$sql="SELECT ranked.id,ranked.recorded_at,ranked.identifier,ranked.person_name,ranked.person_type,ranked.encounter_count,ranked.follow_up_status,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=ranked.id AND observation_code='weight' LIMIT 1) weight,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=ranked.id AND observation_code='bmi' LIMIT 1) bmi,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=ranked.id AND observation_code='temperature' LIMIT 1) temperature,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=ranked.id AND observation_code='blood_pressure_systolic' LIMIT 1) systolic,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=ranked.id AND observation_code='blood_pressure_diastolic' LIMIT 1) diastolic,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=ranked.id AND observation_code='blood_glucose' LIMIT 1) glucose
 FROM (SELECT record.id,record.recorded_at,record.follow_up_status,COALESCE(member.crn,child.srn) identifier,COALESCE(TRIM(CONCAT_WS(' ',member.first_name,member.middle_name,member.last_name)),TRIM(CONCAT_WS(' ',child.first_name,child.middle_name,child.last_name))) person_name,CASE WHEN record.member_id IS NOT NULL THEN 'Member' ELSE 'Sunday School' END person_type,
 ROW_NUMBER() OVER(PARTITION BY COALESCE(CONCAT('m:',record.member_id),CONCAT('s:',record.sundayschool_id)) ORDER BY record.recorded_at DESC,record.id DESC) row_number,
 COUNT(*) OVER(PARTITION BY COALESCE(CONCAT('m:',record.member_id),CONCAT('s:',record.sundayschool_id))) encounter_count
 FROM health_records record LEFT JOIN members member ON member.id=record.member_id LEFT JOIN sunday_school child ON child.id=record.sundayschool_id WHERE record.church_id=? AND record.status<>'voided') ranked {$outerWhere} ORDER BY ranked.person_name";
$pagination=report_paginate_query($conn,$sql,$types,$params);$rows=$pagination['result'];$churches=$superAdmin?$conn->query('SELECT id,name FROM churches ORDER BY name'):null;$page_title='Individual Health Summary';ob_start();
?>
<link rel="stylesheet" href="<?= BASE_URL ?>/assets/css/health-workspace.css"><div class="health-workspace"><form class="report-filter-panel health-filter mb-4" method="get"><div class="form-row"><?php if($superAdmin):?><div class="form-group col-md-4"><label>Church</label><select class="form-control" name="church_id"><?php while($c=$churches->fetch_assoc()):?><option value="<?= $c['id'] ?>" <?= $churchId===(int)$c['id']?'selected':'' ?>><?= htmlspecialchars($c['name']) ?></option><?php endwhile;?></select></div><?php endif;?><div class="form-group col-md-6"><label>Person / CRN / SRN</label><input class="form-control" name="person" value="<?= htmlspecialchars($search) ?>"></div><div class="form-group col-md-2 d-flex align-items-end"><button class="btn btn-primary btn-block">Filter</button></div></div></form><div class="health-panel"><div class="health-panel-header"><div><h2 class="health-section-title">Individual health summary</h2><p class="health-section-copy">One row per person. Metrics come from the latest encounter only; history remains available through the encounter count.</p></div></div><div class="table-responsive"><table id="individualHealthTable" class="table health-table mb-0" data-report-pagination="server"><thead><tr><th>Person</th><th>Type</th><th>Latest encounter</th><th>Encounters</th><th>Weight</th><th>BMI</th><th>Temperature</th><th>BP</th><th>Glucose</th><th>Follow-up</th></tr></thead><tbody><?php while($row=$rows->fetch_assoc()):?><tr><td><strong><?= htmlspecialchars($row['person_name']) ?></strong><br><small><?= htmlspecialchars($row['identifier']) ?></small></td><td><?= htmlspecialchars($row['person_type']) ?></td><td><?= date('d M Y',strtotime($row['recorded_at'])) ?></td><td><?= number_format((int)$row['encounter_count']) ?></td><td><?= $row['weight']!==null?number_format((float)$row['weight'],1):'—' ?></td><td><?= $row['bmi']!==null?number_format((float)$row['bmi'],1):'—' ?></td><td><?= $row['temperature']!==null?number_format((float)$row['temperature'],1):'—' ?></td><td><?= $row['systolic']!==null?(int)$row['systolic'].'/'.(int)$row['diastolic']:'—' ?></td><td><?= $row['glucose']!==null?number_format((float)$row['glucose'],1):'—' ?></td><td><?= htmlspecialchars(ucfirst($row['follow_up_status'])) ?></td></tr><?php endwhile;?></tbody></table></div><div class="health-panel-body"><?php report_render_server_pagination($pagination['total_rows'],$pagination['page'],$pagination['per_page'],'Individual health summary pages');?></div></div></div><script>$(function(){$('#individualHealthTable').DataTable({paging:false,searching:false,info:false,dom:'Bfrtip',buttons:<?= $canExport?"['copy','csv','excel','pdf','print']":'[]' ?>});});</script>
<?php $page_content=ob_get_clean();require_once __DIR__.'/../../../includes/layout.php';
